// Field manual: the real-world knowledge behind each mechanic. Edition basis of the text: NFPA 13-2025,
// NFPA 20, NFPA 25, NFPA 72 (the enforced NFPA 13 edition is a site setting; plan review cites that one).
// Company rules and ASSUMED / NEEDS PE REVIEW values are listed on the 'site' page. Always verify against
// the edition your jurisdiction adopted.
var DI = globalThis.DI || (globalThis.DI = {});
// Pieces built from the engine tables, so the manual never carries its own copy of a number.
DI.MAN = (function () {
  const f = DI.asdFmt, A = DI.AIR_TEST, R = DI.JURIS;
  // the listed range of every aspirating detector model, per stage, with the datasheet it was read from
  const asd = '<table><tr><th>Model</th>' + DI.ASD_STAGES.map(([, n]) => '<th>' + n + '</th>').join('') + '<th>Datasheet</th></tr>' + Object.keys(DI.ASD_MODELS).map((k) => { const M = DI.ASD_MODELS[k];
    return '<tr><td><b>' + M.label + '</b>' + (k === DI.ASD_DEFAULT ? ' (default)' : '') + '<br>' + M.models + '</td>' + DI.ASD_STAGES.map(([s]) => '<td>' + f(M.range[s][0]) + ' to ' + f(M.range[s][1]) + '</td>').join('') + '<td>' + M.doc + '</td></tr>'; }).join('') + '</table>';
  // the thirteen recovery steps (DI.RECOVERY) with the reason for each
  const why = { 'silence': 'Nothing is reset; you have acknowledged it.', 'find-head': 'Select it on the map.', 'close-valve': 'The tamper supervisory comes in: expected.',
    'isolate-air': 'The supply to this zone only. Left open, the compressor keeps feeding the open pipe.',
    'drain-zero': 'Wait for the gauge. The game confirms it for you once it reads ' + DI.SAFE_PSI + ' psi or less (ASSUMED) and the pipe is empty. Air out an open drain is air: falling pressure and compressor run time, never water flow.',
    'reset-panel-1': 'So detection drops out and the solenoid de-energizes; the riser reset is refused while it is latched. Not applicable when detection never latched.',
    'replace-head': 'From the spare cabinet. Allowed only with the water isolated, the air / N&#8322; supply isolated, and the pipe at about 0 psi with no water. The drain may stay open: &ldquo;close the drain, then replace the head&rdquo; is backward.',
    'reset-valve': 'Only when the valve tripped. After a trip the clapper is reset <b>before</b> the air is restored: the valve is not set until the clapper is closed, so air restored first is not held and counts for nothing.',
    'drain-close': 'After the riser reset. Air cannot build against an open drain.', 'restore-air': 'Reopen the supply and let it build to normal pressure.',
    'reset-trim': 'The pneumatic actuator re-arms once there is air in the pipe. An electric / electric trim has no actuator: not applicable.',
    'reset-panel': 'After the air is back: clears P and the troubles. Reset earlier and P latches straight back.',
    'open-valve': '<b>Mandatory.</b> Until it is open the building is unprotected. A zone will hold only when the panel is reset with the solenoid de-energized, the clapper is reset, P is clear and the air is above low air: opened earlier, the valve trips again. In the scored drill incident the valve refuses to reopen until then. Anywhere else it opens, and the warning lists what is still open (for example &ldquo;head not replaced in&rdquo; the zone).' };
  const rec = '<ol>' + DI.RECOVERY.map(([k, label]) => '<li><b>' + label.replace('N₂', 'N&#8322;') + '.</b> ' + why[k] + '</li>').join('') + '</ol>';
  const air = A.psi + ' psi air held 24 hours; an end reading of ' + A.endMin + ' psi or more passes (a loss of ' + A.drop + ' psi or less)';
  const airRef = 'NFPA 13-2025 ' + R['US-2025'].ref.airTest.split(' ').slice(2).join(' ') + '; 2022 ' + R['US-2022'].ref.airTest.split(' ').slice(2).join(' ') + '; 2019 ' + R['US-2019'].ref.airTest.split(' ').slice(2).join(' ');
  const tail = (x) => x.split(' ').slice(2).join(' ');
  const refill = 'NFPA 13-2025 ' + tail(R['US-2025'].ref.refill) + '; 2019 and 2022 ' + tail(R['US-2019'].ref.refill) + ' (an N&#8322;-only source: 2019 and 2022 ' + tail(R['US-2019'].ref.refillN2) + '; the 2025 N&#8322;-only subsection was not pulled)';
  // cause-and-effect matrix: the rows and tags as the matrix itself lists them (cause.js)
  const ceRows = '<table><tr><th>Input row</th><th>Tag</th></tr>' + DI.CE_ROWS.map((r) => '<tr><td>' + r.label + '</td><td>' + r.tag + '</td></tr>').join('') + '</table>';
  // supervising-station paths: when a dead panel is annunciated, with the section per edition
  const t72 = (ed, k) => R[ed].ref72[k].replace(/^NFPA 72-\d+ /, '');
  const paths = '<table><tr><th>Path to the supervising station</th><th>Dead panel annunciated after</th><th>NFPA 72-2025</th><th>NFPA 72-2019 / 2022</th></tr>' + Object.keys(DI.COMM_PATH).map((k) => { const q = DI.COMM_PATH[k];
    return '<tr><td>' + q.label + (k === DI.COMM_DEFAULT ? ' (default)' : '') + '</td><td>' + DI.delayText(q.delay) + '</td><td>' + t72('US-2025', q.ref) + '</td><td>' + t72('US-2019', q.ref) + (t72('US-2022', q.ref) !== t72('US-2019', q.ref) ? ' / ' + t72('US-2022', q.ref) : '') + '</td></tr>'; }).join('') + '</table>';
  return { asd, rec, air, airRef, refill, ceRows, paths, src: DI.ASD_SRC };
})();
DI.MANUAL = [
  { id: 'play', t: 'How to play', h: `<p>You are the fire protection designer, the commissioning tech and the night operator. Every contract is the same loop: <b>build</b> it, <b>prove</b> it with tests, then <b>survive</b> the drill.</p>
<table><tr><th>Key</th><th>Does</th></tr><tr><td>Q</td><td>Select / operate</td></tr><tr><td>1</td><td>Main pipe (drag). Drag over pipe to resize it</td></tr><tr><td>2</td><td>Sprinkler branch lines (drag a rectangle). R flips direction</td></tr>
<tr><td>3 / 4 / 5 / X</td><td>Single head / air tubing / wiring / erase</td></tr><tr><td>[ &nbsp;]</td><td>Pipe size</td></tr><tr><td>R</td><td>Rotate part</td></tr><tr><td>Space</td><td>Pause</td></tr><tr><td>Ctrl+Z</td><td>Undo</td></tr><tr><td>Right-drag, WASD, wheel</td><td>Pan and zoom</td></tr><tr><td>G / M</td><td>Goals / this manual</td></tr></table>
<p><b>One tile is 10 ft.</b> One sprinkler tile protects 100 ft&sup2;. Branch lines only connect end to end, and to a main beside them. Mains connect to everything they touch.</p>
<p>Pipe colour is what is inside it: blue is water (brighter is higher pressure), sand is compressed air, teal is nitrogen. White dashes are flow. Hover any pipe for pressure, flow and velocity.</p>
<p>Select a riser or pump to operate it and run its tests. <b>Review</b> is the plan checker. <b>Skip</b> jumps ahead in time and stops if an alarm comes in.</p>` },
  { id: 'wet', t: 'Wet pipe systems', h: `<p>Pipe full of water under pressure, closed heat-activated sprinklers. Only the sprinklers that get hot open. Wet is the default: it is the most reliable and it puts water on the fire soonest.</p>
<ul><li><b>Limits:</b> the whole system must stay at 40&nbsp;&deg;F or above. One riser may protect 52,000 ft&sup2; per floor for light and ordinary hazard (NFPA 13-2025 &sect;4.4.1).</li>
<li><b>Riser:</b> control valve with tamper switch, alarm check valve or riser check with a waterflow switch, main drain, gauges above and below.</li>
<li><b>Waterflow alarm:</b> a vane switch has a retard (typically 30&ndash;45 s) so pressure surges do not send the fire department. NFPA 72 wants the signal within 90 s of a flow equal to one sprinkler; NFPA 13 allows 5 minutes for the local alarm.</li>
<li><b>Inspector&rsquo;s test:</b> an orifice equal to the smallest sprinkler, at the remote end. It proves the alarm works with one head flowing.</li>
<li><b>Main drain test:</b> record static, open the 2-inch drain, record residual. Compare with last time. A 10% drop in residual means find the closed valve or the obstruction (NFPA 25).</li></ul>
<p><b>Why not in a data hall?</b> A wet system has one failure mode the owner cannot accept: a single broken or leaking sprinkler puts water on live equipment immediately.</p>` },
  { id: 'dry', t: 'Dry pipe systems', h: `<p>For spaces that freeze: docks, canopies, unheated mechanical yards. The pipe holds compressed air or nitrogen. A <b>differential dry pipe valve</b> has a clapper with a large air seat and a small water seat, so a little air holds back a lot of water, roughly 5.5 to 1.</p>
<ul><li><b>Trip point</b> &asymp; water pressure &divide; 5.5. Air is normally set about 20 psi above it. Remember that a fire pump raises the water pressure, and so the trip point.</li>
<li><b>The delay is the problem.</b> Air must bleed down to the trip point, then water has to push the rest of the air out through one sprinkler.</li>
<li><b>Size limits (NFPA 13-2025 &sect;8.2.4.2, .2.1 and .2.2; in 2019 and 2022 &sect;8.2.3.2 to &sect;8.2.3.4):</b> up to 500 gal needs no delivery test; up to 750 gal with a listed quick-opening device (accelerator). Above that, water must reach the inspector&rsquo;s test in 60 s. The calculation / table route (2025 &sect;8.2.4.3.1 and Table 8.2.4.3.2; 2019 and 2022 Table 8.2.3.6.1: light 60, ordinary 50, extra 45, high-piled storage 40 s) is shown on the test report for information and is not modelled.</li>
<li><b>Zone volume is what counts:</b> pipe plus a fittings allowance plus the valve trim (5 % and 2 gal by default, both ASSUMED project settings). The valve and the trip-test report show the pipe-only figure beside it. A system that reads 498 gal of pipe is a 525 gal zone.</li>
<li><b>Insurer overlay:</b> where the site insurer is FM, dry and double-interlock systems must deliver in 30 s at any volume (FM DS 5-32, NEEDS PE REVIEW). The most stringent limit governs, and the report shows the NFPA limit, the FM limit, the governing one and the margin in seconds.</li>
<li><b>Design area +30%</b> with no density reduction, because the fire is bigger when the water arrives (Ch. 19).</li>
<li><b>No gridding</b> (&sect;8.2.1). Air cannot be swept out of a loop.</li>
<li><b>C-factor 100.</b> Company rule for all sprinkler pipe. Nitrogen protects the pipe and earns no C-factor credit.</li>
<li><b>Air supply</b> must restore normal pressure in 30 minutes (${DI.MAN.refill}). Each dry and preaction valve shows a <b>Refill clock</b> against that limit: it runs from the first gas into the closed-up zone to normal pressure, and reads OK or FAIL. The 2025 acceptance wording (&sect;29.2.3.2.4.1) measures the time to set pressure from the opening of the air supply (from a search, not verbatim: VERIFY). The 60-minute allowance for refrigerated spaces below 5&nbsp;&deg;F (2019 &sect;8.2.6.3.3) is not modelled: there is no freezer room here.</li>
<li><b>Sizing the compressor.</b> scfm minimum = zone volume in cubic feet &times; (normal pressure &divide; 14.7) &divide; 30, taken on the <b>largest</b> zone the compressor serves (one compressor serving several systems is sized on the single largest: Annex A.8.2.6.3.2 in 2019 and 2022). A 525 gal zone is 70.2 ft&sup3;; at 40 psi it needs about 6.4 scfm, about 8 with a &times;${DI.AIR_SIZING.margin} margin (ASSUMED practice), so 10 scfm is reasonable. Plan review warns below the minimum and below the margin; it never fails on it, because the measured clock is the authority. <b>Recovery time is mostly compressor time</b>: the operator&rsquo;s own steps take seconds or minutes, the refill takes the rest. Use <b>Skip the refill</b> on the valve to jump to the end of it.</li>
<li>Low-air and high-air supervisory setpoints are set on each valve (30 and 50 psi around a 40 psi normal by default).</li>
<li><b>Acceptance air test (dry and double interlock):</b> ${DI.MAN.air}. A loss over 1.5 psi must be corrected. The test starts at test pressure: a zone sitting lower is charged to 40 psi first (the game does this for you, a simplification), and a zone above it has to be bled down. The report gives the test pressure, the start and end readings, the pass line with its section, and the drop. Section: ${DI.MAN.airRef} (verified in all three editions). After the test the supply is restored. Where the zone&rsquo;s normal pressure is 40 psi nothing more is needed. Where it is lower the pipe is left high: <b>return it to normal</b> by bleeding at the system drain or the trim, close up, and confirm it sits above low air before close-out (the valve shows the step; practice only). HIGH AIR shows while the pipe is above the high-air setpoint.</li>
<li><b>Loss of supply air</b> is a trouble of its own: every compressor or nitrogen source on the zone has lost power or failed. It arrives beside the low-air supervisory, which only says the pressure is down. Shutting the zone&rsquo;s own supply valve on purpose does not raise it.</li>
<li><b>A closed air supply valve is an impairment:</b> tag it and restore it. It is not a supervisory signal here. The game shows it as an amber <b>IMPAIRMENT TAGS</b> strip above the annunciator and a line on the valve, with or without a live panel. Cause first, symptom second: the low-air supervisory still comes in only when the gauge actually falls.</li>
<li>Pipe is pitched back to drain; low points get drum drips that someone has to empty before winter.</li></ul>
<p>A dry system does <b>not</b> protect against accidental discharge. Break a sprinkler and the valve trips.</p>` },
  { id: 'pre', t: 'Preaction systems', h: `<p>A deluge-type valve, closed sprinklers, supervisory gas in the pipe and a detection system. This game builds one kind only: <b>double interlock</b>. Water enters the pipe when two things are both true.</p>
<table><tr><th>Leg</th><th>True when</th><th>Held by</th></tr><tr><td><b>D</b> detection</td><td>aspirating detection is at or above <b>Fire 1</b> (a level check, so a jump straight to Fire 2 is D), or one listed spot detector alarms in an electrical / UPS room, or someone operates a manual release station wired to the panel (typed DETECTION)</td><td>a latch in the releasing panel</td></tr>
<tr><td><b>P</b> pressure</td><td>pipe pressure falls below the <b>P trip</b> setpoint</td><td>a latch, until someone resets it where that trim holds it</td></tr></table>
<p><b>Release = D AND P.</b> A broken sprinkler alone gives P and no water. A false detection alone gives D and no water.</p>
<p>The full formula has a second path that is off unless the project turns it on: <b>Release = (D AND P) OR (bypass 9(c) AND Manual Release zone)</b>, the second term on an electric / electric trim only. The valve&rsquo;s inspector names the path in its <b>Release path</b> row:</p>
<table><tr><th>Release path row</th><th>Means</th></tr><tr><td>(D AND P) armed</td><td>normal: water needs both legs</td></tr><tr><td>Manual Release zone BYPASS ARMED (9(c), NEEDS PE REVIEW)</td><td>the project flag is ON on this electric / electric valve and the zone is idle</td></tr>
<tr><td>Manual Release zone RELEASING - without P</td><td>the zone has latched its own release. D reads normal, by design: the zone is not detection</td></tr></table>
<ul><li><b>P is a threshold, not a cause.</b> The sensor reads pipe pressure and nothing else. An open sprinkler, an open inspector&rsquo;s test and a broken pipe all look the same to it: any opening big enough to beat the compressor. A slow leak the compressor keeps up with never reaches P trip and gives a low-air supervisory only.</li>
<li><b>The trim decides the sensor, the solenoid and the reset.</b>
<table><tr><th>Trim</th><th>P sensed by</th><th>Solenoid energized on</th><th>Valve opens on</th><th>P is reset</th></tr><tr><td>Electric / electric</td><td>pressure switch PSL-REL, latched in the panel</td><td>D AND P</td><td>D AND P</td><td>at the releasing panel</td></tr>
<tr><td>Electric / pneumatic</td><td>pneumatic actuator PA-REL, at the valve</td><td>D alone</td><td>D AND P</td><td>at the actuator, at the trim</td></tr></table></li>
<li><b>Resetting.</b> A panel reset clears the panel&rsquo;s latches and then reads every input again, so a live input comes straight back. On electric / electric, P clears with the panel reset once the pipe is back above P trip; reset earlier and it latches again. On electric / pneumatic a panel reset cannot clear P: restore the air, then reset the actuator at the trim. On both trims a tripped valve is reset by hand at the riser, a panel reset never closes it, and the riser reset never clears P.</li>
<li><b>Setpoints live on each valve</b> and load from the maker trim preset. The order is always high-air supervisory &gt; normal &gt; low-air supervisory &gt; P trip, with low air at least 5 psi above P trip so the warning arrives first. Defaults are 50 / 40 / 30 / 20 psi. All of these numbers are ASSUMED and adjustable.</li>
<li><b>Low air and high air are supervisory only.</b> They follow live pressure and never release anything. P latches: it stays true after the air comes back, until it is reset.</li>
<li><b>A latched P on the annunciator</b> is a release input whose signal class has not been elected. It shows as an OPEN item, and the class is a site setting: alarm or trouble if the engineer elects one, never supervisory (NEEDS PE REVIEW).</li>
<li>Double interlock is treated like dry pipe for delay: <b>+30% design area, no gridding</b>, and the <b>60 s timed trip test above 500 gal of zone volume</b> (NFPA 13-2025 &sect;8.3.2.3.1.1). A quick-opening device may help meet the 60 s but does not extend the 500 gal: there is no 750 gal exemption for double interlock. Minimum <b>7 psi</b> supervisory pressure.</li>
<li><b>Panel failure never releases water.</b> The solenoid is energize-to-release. The releasing panel runs on standby batteries when utility power fails (about 24 h of standby plus alarm here, a simplification). It shows AC failure at the panel at once and transmits it to the supervising station after the site&rsquo;s delay (60 to 180 minutes). LOW BATTERY comes in at the battery&rsquo;s listed low-voltage setpoint, represented here as 1/12 of capacity left (ASSUMED, NEEDS PE REVIEW): the code sets no low-battery threshold. A dead panel leaves the valve shut. Recovery is the mechanical emergency release by a person.</li>
<li><b>A dead panel is dark.</b> No display, no LEDs, nothing to silence and nothing to reset: the buttons say so. The status bar reads PANEL DEAD at once, because you can see the dark panel. The supervising station cannot: it annunciates the loss of communication only after its supervision interval (60 minutes on a single IP path, a site setting), and only then does that line appear on the annunciator. On the valve, the rows the panel feeds read <i>not displayed: panel dead</i>. What is left is mechanical: the gauges, the valve itself, and on an electric / pneumatic trim the actuator&rsquo;s own P.</li>
<li><b>Power coming back is not a release; the inputs are.</b> On an electric / electric trim the P latch lives in the panel&rsquo;s memory, so a dead panel holds none (ASSUMED simplification: lost and re-read, not stored). When power returns the panel reads its inputs again: P comes back on the spot if the pipe is still below P trip, and D if detection is still reading Fire 1. If both are true the valve trips, as it should.</li>
<li><b>Mechanical emergency release.</b> A hand valve at the trim that opens the preaction valve directly, outside the panel logic. No detection and no P are needed. The sprinklers are still closed, so water flows only where a sprinkler is open.</li>
<li><b>Manual station.</b> A manual release station is a device wired to the releasing panel. It is typed DETECTION: it sits inside D for every preaction valve that protects the room it is in, and water still needs P. It stays operated until it is reset at the station. A Manual Release zone that bypasses P is a per-project setting, OFF by default, and NEEDS PE REVIEW (owner/insurer exception, footnote 9(c)). It is a separate release path, not detection: it does not latch D, and it latches its own release, which stays latched after the station is reset until the panel is reset. In a contract an ON bypass is an impairment: a supervisory on the panel and a tag on the valve.</li></ul>
<p><b>The trap:</b> low air alone is supervisory, and it is the operator&rsquo;s window: it arrives above P trip. A slow air loss that is left alone reaches P trip and latches P, because the sensor reads pressure, not the rate of decay. With P latched (broken head, broken pipe, big leak, an unattended slow leak) any detection event trips the valve and the pipe fills. If a head is open or broken it discharges. If every head is closed the zone is water-filled and nothing discharges: that is a recovery event, not a discharge. Drain it, reset it, check for freeze and corrosion exposure, and fix the air supply. So after every repair restore the air and then reset P. A pipe break plus a detection event floods the room. A panel left latched in Fire 1 leaves only P between the pipe and the water.</p>
<p style="color:#7f93a3">Comparison only: NFPA 13 &sect;8.3 also defines single interlock (detection alone admits water) and non-interlock (detection or pressure loss) preaction. They are not built here.</p>` },
  { id: 'gas', t: 'Air, nitrogen and corrosion', h: `<p>Steel + water + oxygen = rust. Dry and preaction pipe is never really dry: hydrotests and trip tests leave water in the low points, and compressed air keeps delivering fresh oxygen at 21%. The result is pinhole leaks at the water line, usually within 5 to 10 years, and a compressor that never stops.</p>
<ul><li><b>Nitrogen generators</b> (membrane or PSA) supply 98%+ nitrogen. With oxygen under about 2% the reaction starves.</li><li>The oxygen already in the pipe has to be <b>purged</b>. A vent at the far end bleeds gas while the generator makes it up (&ldquo;fill and purge&rdquo;); an analyzer closes it at 98%. Expect one to two weeks. Without a vent, dilution relies on leakage and takes months.</li>
<li>Generators are small. The 30-minute fill is usually done by an air compressor, with nitrogen taking over for maintenance.</li>
<li><b>Symptoms to read:</b> compressor run time creeping up, low-air supervisories at night when the pipe cools, a failed 24-hour air test.</li></ul>` },
  { id: 'pump', t: 'Fire pumps', h: `<p>A fire pump adds pressure. It does not make water. NFPA 20 fixes the shape of the curve:</p>
<table><tr><th>Point</th><th>Flow</th><th>Pressure</th></tr><tr><td>Churn (shutoff)</td><td>0</td><td>no more than 140% of rated</td></tr><tr><td>Rated</td><td>100%</td><td>100%</td></tr><tr><td>Overload</td><td>150%</td><td>at least 65%</td></tr></table>
<ul><li>Pick the pump so the system demand lands between about 90% and 140% of rated flow. Never design beyond 150%.</li><li>System components must be rated for <b>churn + maximum suction pressure</b>.</li><li>Suction pressure must stay at or above 0 psi at 150% flow.</li>
<li><b>Electric:</b> listed controller, starts on pressure drop, runs until stopped by hand. Needs a reliable source; otherwise a second source or a second driver.</li><li><b>Diesel:</b> fuel tank 1 gal per hp + 5% expansion + 5% sump, kept at least two-thirds full; two battery sets; engine block heater.</li>
<li><b>Weekly / monthly churn run</b> (NFPA 25): diesel 30 minutes weekly. Electric 10 minutes, weekly when it draws from a ground-level tank.</li><li><b>Annual flow test</b> through the test header: churn, 100%, 150%. Acceptance is at least 95% of the rated curve.</li>
<li>The pressure <b>sensing line</b> connects downstream of the pump&rsquo;s discharge check valve, one per pump.</li></ul>
<p><b>Tank:</b> the pump sets pressure, the tank sets time. Size it for sprinkler demand plus hose stream for the duration: 30 min light hazard, 60&ndash;90 ordinary, 90&ndash;120 extra.</p>` },
  { id: 'set', t: 'Jockey pump and pressure settings', h: `<p>Every piping system leaks a little. Without a jockey (pressure maintenance) pump, system pressure sags until the fire pump starts, and a fire pump start is an alarm.</p><p>NFPA 20 Annex A.14.2.6 gives the usual ladder:</p>
<table><tr><th>Setting</th><th>Value</th></tr><tr><td>Jockey <b>stop</b></td><td>fire pump churn pressure + minimum static suction pressure</td></tr><tr><td>Jockey <b>start</b></td><td>at least 10 psi below jockey stop</td></tr><tr><td>Fire pump <b>start</b></td><td>5 psi below jockey start</td></tr><tr><td>Each additional pump</td><td>10 psi lower again</td></tr></table>
<p>Example: 100 psi pump, churn 120, tank suction 10 &rarr; jockey stop 130, jockey start 120, fire pump 115, lag pump 105.</p><p>If the jockey cycles every few minutes there is a real leak. Find it; do not widen the band.</p>` },
  { id: 'hyd', t: 'Hydraulics', h: `<p><b>Sprinkler:</b> Q = K &radic;P. A K5.6 head at 7 psi (the minimum) flows 14.8 gpm; at 28 psi it flows twice that, not four times.</p><p><b>Pipe friction (Hazen-Williams):</b> p = 4.52 Q<sup>1.85</sup> / (C<sup>1.85</sup> d<sup>4.87</sup>) psi per foot. Diameter is raised to almost the fifth power: one size up roughly thirds the loss.</p>
<table><tr><th>Pipe</th><th>C</th></tr><tr><td>All sprinkler pipe: wet, dry, preaction, interior, yard and underground</td><td>100 (company rule)</td></tr></table>
<p style="color:#7f93a3">Comparison only: the NFPA table value is 120 for wet steel. The company uses 100, and nitrogen earns no credit. This line has no effect on any calculation.</p>
<p><b>Pipe schedule</b> sets the inside diameter. One size cut decides it, regardless of main or branch: the cut size and smaller is threaded Schedule 40, every larger size is roll-grooved Schedule 10. The cut is a project setting, 2 in. by default (ASSUMED), and can be moved between 1&frac12; in. and 4 in. in the Sandbox. A 2 in. pipe is 2.067 in. inside as Schedule 40 and 2.157 in. as Schedule 10. 12 in. Schedule 10 (12.390 in. inside) is for above-ground headers only; underground and yard pipe is a different material and is not modelled.</p>
<p><b>The hydraulic calc checks hydraulics only.</b> Coverage belongs to plan review. If a room the system serves is not fully sprinklered, the calc result reads &ldquo;PASS (hydraulics only); coverage FAIL, see plan review&rdquo;.</p>
<p><b>Density / area method</b> (NFPA 13-2025 Ch. 19): every sprinkler in the hydraulically most remote area must deliver the design density.</p>
<table><tr><th>Hazard</th><th>Density</th><th>Area</th><th>Hose</th><th>Duration</th></tr><tr><td>Light</td><td>0.10</td><td>1,500</td><td>100</td><td>30</td></tr><tr><td>Ordinary 1</td><td>0.15</td><td>1,500</td><td>250</td><td>60&ndash;90</td></tr><tr><td>Ordinary 2</td><td>0.20</td><td>1,500</td><td>250</td><td>60&ndash;90</td></tr><tr><td>Extra 1</td><td>0.30</td><td>2,500</td><td>500</td><td>90&ndash;120</td></tr></table>
<p>The remote area is a rectangle 1.2&radic;A long, parallel to the branch lines. Dry and double-interlock systems add 30% to A.</p>
<p><b>What starves the far end:</b> long dead-end branch lines, small cross mains, feeding from one corner. <b>What fixes it:</b> feed from the middle, step pipe sizes up toward the riser, shorten the lines.</p>` },
  { id: 'sig', t: 'Detection and signals', h: `<p>NFPA 72 sorts everything into three kinds of signal. Knowing which is which is half of operating a site.</p>
<table><tr><th>Signal</th><th>Means</th><th>Examples</th></tr><tr><td style="color:#ff4b3a">ALARM</td><td>fire, now</td><td>waterflow, aspirating Fire 1 and Fire 2, spot smoke detection, manual station</td></tr><tr><td style="color:#ffb224">SUPERVISORY</td><td>the protection is impaired</td><td>valve tamper (2 turns or 1/5 travel), low or high air (per-valve setpoints), aspirating Alert and Action, pump running, pump power loss, low fuel, low tank, room below 40&nbsp;&deg;F, a Manual Release zone bypass in a contract</td></tr>
<tr><td style="color:#ffe45c">TROUBLE</td><td>the alarm system itself is impaired</td><td>panel AC failure, low battery, loss of communication with a dead panel (reported by the supervising station, after its supervision interval), loss of supply air (compressor or nitrogen source unavailable)</td></tr>
<tr><td style="color:#c59bff">OPEN</td><td>release input, class not elected</td><td>P latched on a preaction valve (PSL-REL or PA-REL)</td></tr></table>
<h4>SIGNAL CLASSES</h4><table><tr><th>Signal</th><th>Class</th><th>Setting</th></tr><tr><td>Aspirating Alert, Action</td><td>supervisory (pre-alarm)</td><td>supervisory or alarm. ASSUMED, NEEDS PE REVIEW</td></tr><tr><td>Latched P (release input)</td><td>OPEN: not elected</td><td>not elected, alarm or trouble. Supervisory is blocked. ASSUMED, NEEDS PE REVIEW</td></tr>
<tr><td>Fire 1, Fire 2, manual station, waterflow</td><td>alarm</td><td>fixed</td></tr><tr><td>Low air, high air, valve tamper</td><td>supervisory</td><td>fixed</td></tr><tr><td>Panel AC failure, low battery, loss of communication (dead panel)</td><td>trouble</td><td>fixed</td></tr><tr><td>Loss of supply air</td><td>trouble</td><td>fixed (PRACTICE). A compressor or nitrogen power or controller fault is equipment trouble, its own signal; the pressure drop it causes is still reported by the low-air supervisory</td></tr></table>
<p>A closed air supply valve is an impairment: tag it and restore it. It is not a supervisory signal here.</p>
<p>The annunciator lists alarm first, then OPEN items, then supervisory, then trouble. Its banner reads OPEN ITEM only when nothing else is present (ASSUMED presentation). Each class has its own sound: a bell for alarm, a two-tone chirp for an OPEN item, a short beep for supervisory, a low pulse for trouble (ASSUMED presentation). <b>Silence</b> on the panel acknowledges the signals: nothing is reset, nothing clears, and a new signal sounds again. A dead panel shows and sounds nothing; its line on the annunciator is the supervising station&rsquo;s.</p>
<p><b>Aspirating smoke detection</b> (VESDA and similar) draws air through sampling pipe to a laser chamber. It reports in stages:</p><ul><li><b>Alert</b>: pre-alarm. It never arms a release. Investigate: this is the stage where a person with a CO&#8322; extinguisher wins.</li><li><b>Action</b>: pre-alarm. Still no release.</li><li><b>Fire 1</b>: alarm, and the detection leg of the preaction release: D is true whenever the level is at or above Fire 1. Water still needs P.</li><li><b>Fire 2</b>: escalation only. It is never a release input by itself.</li></ul>
<p>A reading that jumps past several thresholds at once is logged stage by stage, in order, at the same time: Alert, Action, Fire 1, Fire 2. The detector reports its highest stage; the stages below it stay on the annunciator, struck through, as the record.</p>
<p>The four thresholds are a site setting, owner-set inside the listed range of the detector model: ASSUMED, NEEDS PE REVIEW. 0.03 / 0.06 / 0.12 / 1.2 %/ft are example values; the datasheets print setting ranges, not defaults. They must run Alert &lt; Action &lt; Fire 1 &lt; Fire 2, and <b>every</b> stage must sit inside its own listed range for the model chosen under Site. Listed ranges, %/ft obscuration ${DI.MAN.src}:</p>
${DI.MAN.asd}
<p>A value outside its range is never clamped: it stays as typed, shows red in the Site dialog and fails plan review. Changing the model never changes a threshold. The spot detector threshold is a site setting too: 1.3 %/ft inside an example window of 0.5 to 4.0 %/ft.</p>
<p><b>NFPA 76, where adopted</b> (NFPA 76-2024 &sect;8.5.3.1.2.5): two plain ceilings. Alert at 0.2 %/ft or less, and the alarm ceiling of 1.0 %/ft applied to <b>Fire 1</b>, the first alarm stage. Action stays pre-alarm and Fire 2 has no NFPA 76 limit (PRACTICE, NEEDS PE REVIEW). There is no real conflict with the detector listing: the listed Fire 1 maximum of both models (0.614 %/ft) is tighter, so the listing binds first and the 1.0 ceiling can never be the limit. The Site dialog and plan review say so in one note. Plan review fails an Alert above 0.2 or a Fire 1 above 1.0. <b>Check against NFPA 76</b> under Site reads the thresholds against the two ceilings and writes nothing.</p>
<p><b>Spot detectors</b> need far more smoke, so they answer later. In white space a spot detector raises the alarm only, and release needs aspirating detection. In a support room (electrical, UPS) one listed, compatible spot detector in alarm is the detection leg: any one detector in the zone, and D AND P is still the double interlock.</p><p>An unwired switch still clicks. Nobody hears it. In this game an unwired device shows as <i>local only</i> and the fire department is not called.</p>
<h4>WHEN THE SUPERVISING STATION KNOWS (NFPA 72)</h4>
<ul><li><b>Trouble at the panel:</b> within ${DI.TROUBLE_PANEL_S} seconds (&sect;10.15.1, the same in 2019, 2022 and 2025). The game shows panel troubles at once, which is inside that ceiling.</li>
<li><b>AC failure</b> is transmitted to the supervising station after a delay of 60 to 180 minutes (&sect;10.6.9.3), an owner / AHJ setting under Site, 60 by default. If power comes back inside the delay nothing is sent. Until it is sent the annunciator row says so.</li>
<li><b>Low battery:</b> the code requires the battery voltage to be monitored and a trouble on failure, and states no low-battery threshold (&sect;10.6.9.1; &sect;10.6.10.6 is charger failure). The 24 h of standby sets capacity, not the trouble setpoint. The trouble here is ${DI.LOWBATT_NOTE}. It is transmitted at once (ASSUMED).</li>
<li><b>A dead panel</b> sends nothing, so the station learns of it only when its supervision of the path runs out. That depends on the path, a site setting:</li></ul>
${DI.MAN.paths}
<p>The DACT figure is its 6-hour test-signal interval: a missed test is a trouble, but no deadline for annunciating it is held, so the interval is used as the delay (ASSUMED, VERIFY). Two-way radio paths and the DACT 4-minute channel-failure rule are not modelled. The NFPA 72 edition follows the NFPA 13 edition of the site (ASSUMED; a real AHJ adopts them separately).</p>` },
  { id: 'ce', t: 'Cause and effect', h: `<p>A cause-and-effect matrix says, for every input on a zone, what the fire alarm system does about it. Open it from a preaction valve (<b>Cause and effect matrix</b>) or from the releasing panel, which offers one per wired zone. It is read-only, and it is <b>generated</b>, not written: the signal classes come from the registry the alarm code itself reads, and the solenoid column from the release formula on that zone&rsquo;s trim and bypass setting. The tests hold every row against the fire alarm lead&rsquo;s truth table and against the running engine.</p>
<table><tr><th>Column</th><th>Says</th><th>Basis</th></tr>
<tr><td>Input, Tag</td><td>the input the row stands for, and where its rule comes from</td><td>see the tags below</td></tr>
<tr><td>SignalClass</td><td>alarm, supervisory, trouble, or pre-alarm (Alert and Action)</td><td>[CODE] for the three classes; [OWNER] for how pre-alarm is handled</td></tr>
<tr><td>PanelAnnunciation</td><td>zone-identified display and audible at the panel; a dead panel displays nothing</td><td>[CODE]</td></tr>
<tr><td>SS_Transmit</td><td>what the supervising station receives, and when (see &ldquo;When the supervising station knows&rdquo; under Detection and signals)</td><td>[CODE] for alarm, supervisory and trouble; [OWNER] for pre-alarm</td></tr>
<tr><td>LocalNAC</td><td>alarm only. Supervisory and trouble never sound the notification appliances</td><td>[CODE]. Here it is a rule read from the class: notification circuits are not modelled</td></tr>
<tr><td>Solenoid</td><td>electric / electric: energized only when D AND P. Electric / pneumatic: energized on D, and water also needs P at the actuator</td><td>[PRACTICE]</td></tr>
<tr><td>HVAC_Hook</td><td>an output contact for CRAH / AHU shutdown or a damper, where elected</td><td>[OWNER], NEEDS PE REVIEW. Default none</td></tr>
<tr><td>EPO_Hook</td><td>an output contact for power isolation, where elected</td><td>[OWNER], NEEDS PE REVIEW (an NEC 645 / FM DS 5-32 election). Default OFF</td></tr></table>
<p><b>Tags:</b> ${DI.CE_LEGEND.join('; ')}.</p>
${DI.MAN.ceRows}
<ul><li><b>P is OPEN, never supervisory.</b> A latched P is a release input whose class the engineer has not elected. It shows OPEN until it is elected alarm or trouble under Site. Supervisory is blocked for it, on both trims.</li>
<li><b>Hooks are hooks only, never automatic.</b> Electing one under Site puts an output contact in the matrix for others to wire. The game shuts down no fan, no damper and no power, and nothing in the plant changes. Which rows carry a hook is ASSUMED, NEEDS PE REVIEW: HVAC on rows where an alarm is annunciated, EPO on rows where the valve opens.</li>
<li><b>Greyed rows</b> are paths that exist but not on this site: the Manual Release zone with the 9(c) bypass OFF or on an electric / pneumatic trim, the DETECTION station with the bypass ON, the tamper row with no control valve.</li>
<li><b>ACTIVE NOW</b> marks the rows whose signal is present on the zone, and follows the plant while the dialog is open.</li>
<li><b>Low and high air</b> are supervisory and never a release input. <b>Loss of supply air</b> is trouble: equipment trouble, its own signal (PRACTICE).</li></ul>
<p style="color:#7f93a3">${DI.CE_EXCLUDED} The matrix is the first slice of the fire alarm work: the signal schedule, battery and standby, and notification circuits come later.</p>` },
  { id: 'itm', t: 'Testing and maintenance', h: `<p>NFPA 13 says how to build it. NFPA 25 says how to keep it working. The numbers you will use most:</p>
<table><tr><th>Item</th><th>Frequency</th></tr><tr><td>Control valves (supervised)</td><td>inspect monthly; full operation annually</td></tr><tr><td>Dry / preaction air and water gauges</td><td>weekly, or monthly if supervised</td></tr><tr><td>Main drain test</td><td>annually; quarterly behind a backflow preventer on a sole supply</td></tr>
<tr><td>Waterflow alarm devices</td><td>semi-annually (vane and pressure switch)</td></tr><tr><td>Dry valve partial trip</td><td>annually</td></tr><tr><td>Dry valve full-flow trip</td><td>every 3 years</td></tr><tr><td>Dry system air leakage</td><td>every 3 years</td></tr><tr><td>Preaction valve trip</td><td>annually</td></tr>
<tr><td>Low-point drains</td><td>before and during freezing weather</td></tr><tr><td>Fire pump churn run</td><td>weekly (diesel 30 min, electric 10 min)</td></tr><tr><td>Fire pump flow test</td><td>annually</td></tr><tr><td>Internal pipe assessment</td><td>every 5 years</td></tr></table>
<h4>AFTER A TRIP OR A BROKEN HEAD: PUTTING IT BACK</h4><p>One sequence of thirteen steps, in the physical order. It is generic practice (NFPA 25 and maker IOMs); the valve maker&rsquo;s IOM governs the specifics: the reset procedure, the trim reset, how slowly to open the control valve. A step that does not apply counts as done.</p>${DI.MAN.rec}
<p><b>Two panel resets, for two reasons.</b> Reset #1 clears detection so the clapper can be reset. Reset #2 comes after the air is back and clears P and the troubles. A reset while the pipe is still below P trip latches P again and scores nothing.</p>
<p><b>Scored once, practised everywhere.</b> Only the broken-sprinkler incident in the contract 5 drill is scored: 13 of 13 in order earns the star. The time bonus reads <b>operator-step time only</b>, against a ${DI.RECOVERY_TARGET} s target (ASSUMED, informational, not a pass or fail). The air refill is compressor time and gets its own line against the 30-minute limit (&ldquo;Air refill: 12.2 min, limit 30 min: OK&rdquo;), with the total beside it: recovery time is mostly compressor time, and waiting for it is not punished. Every other recovery, after a trip test or in the Sandbox, is practice: the valve shows a <b>Recovery checklist (PRACTICE)</b> with each step done, pending or not applicable, and nothing gates on it.</p>
<p>Until the control valve is open again the building is unprotected. That time is the impairment, and it should be short.</p>` },
  { id: 'dc', t: 'Data center notes', h: `<ul><li><b>Data halls and electrical rooms:</b> double-interlock preaction is the usual owner and insurer position (FM Global Data Sheet 5-32), with aspirating detection. Hazard is commonly taken as Ordinary Hazard Group 1 or 2 depending on the owner standard.</li>
<li><b>Hot / cold aisle containment</b> is an obstruction. Either sprinklers go inside it, or the containment is arranged to drop away or not obstruct (NFPA 75 / 76). The 2025 edition of NFPA 13 adds requirements for <i>supplemental</i> sprinklers below obstructions.</li>
<li><b>System count:</b> a hyperscale hall is far larger than one 500-gal preaction system. Halls are zoned into several valves, each with its own detection zone. Count the zone volume, not the pipe alone: fittings and trim tip a 498 gal layout over 500 gal, and then it has to pass the 60 s timed test or be rezoned. Where FM insures the site the limit is 30 s at any volume (FM DS 5-32, NEEDS PE REVIEW), so a zone can pass NFPA 13 and fail FM.</li><li><b>Battery rooms</b> (lithium-ion): NFPA 855 drives higher densities and often dedicated systems; treat this game&rsquo;s OH2 as a placeholder.</li>
<li><b>Loading docks, generator enclosures, exterior canopies:</b> dry pipe.</li><li><b>Water supply:</b> rural sites mean tanks and redundant pumps (commonly one electric and one diesel, or N+1 diesel), on a looped yard main with sectional valves so one break does not isolate a building.</li>
<li><b>Nitrogen</b> is standard on preaction and dry systems at this scale.</li></ul>` },
  { id: 'site', t: 'Site settings and company rules', h: `<p>The <b>Site</b> button holds the settings that belong to the project, not to one valve. In a contract they are read-only: the basis of design is fixed by the AHJ, the owner and the insurer. They can be changed in the Sandbox. Two labels are used everywhere in the game:</p>
<ul><li><b>ASSUMED</b>: a value the company has not fixed. It is a tunable default, not a rule.</li><li><b>NEEDS PE REVIEW</b>: a choice an engineer of record has to make.</li></ul>
<h4>COMPANY RULES (LOCKED)</h4><ul><li>Wet, dry and double-interlock preaction systems only.</li><li>Preaction release = (D AND P) OR (bypass 9(c) AND Manual Release zone), where D = Fire 1 detection OR a manual station typed DETECTION. The second path is electric / electric only, OFF by default, NEEDS PE REVIEW. Low air is supervisory only and never a release input.</li><li>Only Fire 1 releases. Alert never arms. Fire 2 never releases by itself.</li>
<li>Panel failure never releases water.</li><li>Hazen-Williams C = 100 for all pipe. No nitrogen credit.</li><li>The release truth table is the fire alarm lead&rsquo;s file, copied byte for byte and pinned by its hash. It is never edited in the game&rsquo;s repository.</li></ul>
<h4>ENFORCED EDITION</h4><p>NFPA 13-2019, 2022 or 2025 for US sites, default 2025. Plan review and the trip-test report cite the chosen edition, and plan review shows the delta from 2025 on its first line. Pass and fail do not differ by edition in this version.</p>
<h4>INSURER</h4><p>None by default. With FM, dry and double-interlock systems must deliver water in 30 s at any volume, and the most stringent limit governs. Every contract is winnable with the default.</p>
<h4>ASSUMED VALUES</h4><table><tr><th>Item</th><th>Default</th></tr><tr><td>Preaction setpoints (per valve, from the maker trim)</td><td>high 50, normal 40, low 30, P trip 20 psi</td></tr><tr><td>Minimum margin, low air above P trip</td><td>5 psi</td></tr>
<tr><td>Pipe size cut (largest size on threaded Schedule 40)</td><td>2 in.; larger sizes Schedule 10; same cost per size</td></tr><tr><td>Zone volume: fittings allowance, trim volume</td><td>5 % of pipe volume, 2 gal per valve</td></tr><tr><td>Aspirating thresholds (owner-set example values inside the model&rsquo;s listed range; also NEEDS PE REVIEW)</td><td>0.03 / 0.06 / 0.12 / 1.2 %/ft</td></tr>
<tr><td>Spot detector alarm threshold (example value) and window</td><td>1.3 %/ft inside 0.5 to 4.0 %/ft</td></tr>
<tr><td>Signal class of Alert and Action</td><td>supervisory</td></tr><tr><td>Signal class of a latched P; banner priority of an OPEN item</td><td>not elected (OPEN); shown only when nothing else is present</td></tr>
<tr><td>Releasing panel standby battery</td><td>${DI.PANEL_STANDBY_H} h</td></tr><tr><td>Panel LOW BATTERY trouble: the listed low-voltage setpoint (OWNER/listing; also NEEDS PE REVIEW)</td><td>1/12 of battery capacity left; transmitted at once</td></tr>
<tr><td>NFPA 72 edition</td><td>follows the NFPA 13 edition of the site</td></tr><tr><td>Supervising station on a DACT: delay before a dead panel is annunciated (VERIFY)</td><td>6 h, its test-signal interval</td></tr><tr><td>Supervising station on multiple paths, 2025 edition (annunciation time not found: VERIFY)</td><td>6 h, as in 2019 and 2022</td></tr>
<tr><td>Compressor sizing margin on the 30-minute minimum</td><td>&times;${DI.AIR_SIZING.margin}</td></tr><tr><td>Cause-and-effect hooks: which rows carry them (also NEEDS PE REVIEW)</td><td>HVAC where an alarm is annunciated; EPO where the valve opens</td></tr>
<tr><td>Electric / electric P latch with the panel dead</td><td>lost with panel power, read again on restore</td></tr><tr><td>&ldquo;About 0 psi&rdquo; before a head is replaced (the gate itself is confirmed; the value is ASSUMED)</td><td>${DI.SAFE_PSI} psi</td></tr>
<tr><td>24 h air test: start tolerance, time allowed to charge to test pressure</td><td>${DI.AIR_TEST.tol} psi, ${DI.AIR_TEST.chargeMax / 60} min</td></tr><tr><td>Operator log size</td><td>${DI.ACTS_MAX} entries</td></tr><tr><td>Sound cue per signal class</td><td>bell, chirp, beep, pulse</td></tr>
<tr><td>Contract 5 recovery time bonus target (operator-step time; the air refill is judged separately against 30 min)</td><td>${DI.RECOVERY_TARGET} s</td></tr></table>
<h4>ASPIRATING DETECTOR MODELS: LISTED RANGES</h4><p>Each listing bounds every threshold per stage, per model. The ranges are read from the maker&rsquo;s own datasheets ${DI.MAN.src}: the UL Product iQ listing itself could not be read. The default model is VESDA-E VEP.</p>${DI.MAN.asd}
<p>${DI.ASD_RECORDED.VEA.note} Not offered either: FAAST LT-200 and FLEX (no UL 268 or FM listing on the sheets), TITANUS and FAAST XM / XS (conflicting or non-current sheets).</p>
<h4>NEEDS PE REVIEW</h4><ul><li>Manual Release zone that bypasses P (OFF by default; owner/insurer exception; shown as an impairment in a contract).</li><li>Signal classes: Alert and Action (supervisory by default), and a latched P (class not elected; supervisory blocked). Loss of supply air is settled: trouble (PRACTICE).</li><li>Aspirating default thresholds (0.03 / 0.06 / 0.12 / 1.2 %/ft): owner-set inside the model range. The datasheets print no defaults.</li><li>NFPA 76 ceilings: Alert 0.2 %/ft, and the 1.0 %/ft alarm ceiling applied to Fire 1, with Action as pre-alarm (PRACTICE).</li><li>HVAC and EPO hooks: the owner&rsquo;s election, which rows they appear on, and the NEC 645 / FM DS 5-32 interface.</li><li>Low-battery setpoint: the listed manufacturer voltage setpoint (OWNER/listing).</li><li>AC-fail transmission delay, 60 to 180 minutes (OWNER / AHJ), and the supervising-station path type (OWNER).</li><li>FM 30 s water delivery at any volume for dry and double interlock (FM DS 5-32), applied only when the insurer setting is FM.</li><li>Lithium-ion / ESS room density and approach. The battery room here is a placeholder.</li></ul>
<h4>VERIFY BEFORE USE</h4><p>Verified since the last cycle: the 24 h air test section in every edition (2019 &sect;28.2.2.1; 2022 and 2025 &sect;29.2.2.1), and the 30-minute refill (2019 and 2022 &sect;8.2.6.3.2; 2025 &sect;8.2.7.3).</p><ul><li>The NFPA 13-2022 delivery numbers carried from 2019 and marked (ASSUMED, VERIFY): &sect;8.2.3.2, &sect;8.2.3.3, &sect;8.2.3.4, &sect;8.2.3.5 to .6 and &sect;8.2.3.8. Held for 2022: Table 8.2.3.6.1, &sect;8.2.3.7, &sect;8.3.2.3.1.1 to .4 and &sect;8.3.2.3.2.</li><li>The 2025 acceptance wording for the refill time (&sect;29.2.3.2.4.1: from a search, not verbatim), and the 2025 N&#8322;-only refill subsection (not pulled).</li><li>NFPA 72-2025: the annunciation time for a failed path on multiple paths (&sect;26.6.3.4(1) gives only the 6 h supervision interval), and the deadline for a missed DACT test in every edition.</li><li>The 2019 calculation-route paragraphs (&sect;8.2.3.5 to .6).</li><li>The aspirating ranges against the UL Product iQ listing (read from datasheets only).</li></ul>` },
  { id: 'model', t: 'What the simulation does', h: `<p>So you know what to trust:</p><ul><li><b>Hydraulics:</b> a real network solver (global gradient method, the one in EPANET) on your pipe layout, with Hazen-Williams friction, pump curves, check valves and orifice outlets. Loops work. Fittings are a flat 30% equivalent-length adder. Elevation is ignored except tank level.</li>
<li><b>Gas:</b> each dry or preaction system is one ideal-gas volume with choked-orifice flow through leaks and open sprinklers. Trip time and water transit come out of that, not a table.</li><li><b>Fire:</b> t-squared growth, Alpert ceiling-jet temperatures and RTI link heating (the DETACT method). Water at or above design density knocks the fire down; less only slows it.</li>
<li><b>Simplified:</b> one sprinkler per 10 ft tile, no hangers or seismic bracing, one-storey buildings, corrosion as a single number, smoke as one value per room.</li>
<li><b>Simplified in the release logic:</b> the P sensor goes live the first time a valve is set, so a brand-new valve does not latch P during its first air-up. After a mechanical emergency release with every sprinkler closed, the trapped air is not vented, so the pipe sits pressurized and partly filled with no flow. The panel battery is a flat 24 h. A dead panel&rsquo;s P latch (electric / electric) is lost and read again on restore, not stored. Notification appliances are not modelled.</li>
<li><b>Simplified on purpose in the fire alarm side:</b> the cause-and-effect matrix covers preaction zones only. LocalNAC is a rule read from the signal class, not a circuit. Hooks are display-only and never act. The panel shows power troubles at once (inside the 200 s ceiling). The supervising station learns of a dead panel after the path&rsquo;s supervision interval, as one fixed time. AC-fail transmission uses a fixed delay setting, not a random one. The NFPA 72 edition follows the NFPA 13 edition of the site. The impairment strip is a tag, not a signal.</li>
<li><b>Simplified on purpose in the air supply:</b> the refill clock runs from the first gas into the closed-up zone. The operator-step score leaves out the interval the zone is closed up and filling. One compressor serving several zones refills them at the same time here (the Annex sizes it on the largest single system), so shared-compressor refills run longer than the sizing check implies. The sizing check adds up the ratings of a zone&rsquo;s sources, a nitrogen generator included. A zone counts as back at normal 3.2 psi under its setpoint. The 60-minute refill limit for refrigerated spaces is not modelled. The &ldquo;return to normal&rdquo; step after an air test is practice only, and the bleed at the trim is one click.</li>
<li><b>Simplified on purpose in testing and recovery:</b> the 24 h air test is charged to 40 psi by the game. The &ldquo;confirm 0 psi and no water&rdquo; step is automatic when the conditions hold. Only the system (low-point) drain is scored; the supply-side main drain is optional. A zone with no upstream control valve skips the water-isolation test before a head is replaced. Only the control valve nearest upstream is checked when a zone is reopened. A compressor&rsquo;s own low-air alarm on a separate supply is not modelled.</li>
<li><b>Simplified in water delivery:</b> delivery is judged by the timed trip test only. The calculation / table route is named on the report and not modelled. The inspector&rsquo;s test connection is always present, so the 750 gal trip-test-connection trigger for double interlock is not modelled. FM is the 30 s limit only: no FM density, hose or duration.</li></ul><p>It is a trainer for how these systems behave and why the rules exist. It is not a calculation tool for a submittal.</p>` },
];
